import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第62章 一万两千条","description":"","frontmatter":{},"headers":[],"relativePath":"第62章_一万两千条.md","filePath":"第62章_一万两千条.md"}'),_={name:"第62章_一万两千条.md"};function r(u,p,n,s,q,c){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第62章-一万两千条" tabindex="-1">第62章 一万两千条 <a class="header-anchor" href="#第62章-一万两千条" aria-label="Permalink to &quot;第62章 一万两千条&quot;">​</a></h1><p>那年十一月，我们发了一万两千三百多条。</p><p>这个数我不是猜的。</p><p>十二月我拿一台旧手机做过一次迁移，把那两个号的记录倒出来，导成一个文件。</p><p>文件多大我不说，说了像吹牛。</p><p>我只说结果：十一月，一万两千三百一十七条。</p><p>三十天。</p><p>平均一天四百一十。</p><p>我们一天醒着十六个小时，那就是一个小时二十六条，一分钟两条多。</p><p>我算出这个数的时候，是在自习室，我趴在桌上笑了一下。</p><p>对面那个人抬头看我。</p><p>我说没事。</p><p>我当时心里只有一个念头：我们两个居然说了这么多话。</p><p>一个人一生里能跟另一个人说这么多话吗。</p><p>我们做到了。</p><p>那四百一十条是怎么说出来的，我说几个具体的。</p><p>我们那时候用的是最笨的办法：把一天直播给对方。</p><p>我早上七点起来，我发：今天冷，我那个杯子冻住了。</p><p>她说：什么叫杯子冻住了。</p><p>我说：里面剩下的水结冰了。</p><p>她说：南方会结冰吗。</p><p>我说：我们这边零下。</p><p>她说：零下是多少。</p><p>我说：你那边多少。</p><p>她说：我这里零上六度，但是我感觉像零下二十。</p><p>她说：因为他们家的暖气是坏的。</p><p>我说：修。</p><p>她说：报了，等两周。</p><p>这一段一共十九句。</p><p>这样的十九句，那一天里有二十几段。</p><p>我们不是在讲事情。</p><p>我们是把一件事情拆成十九个回合，然后各人在自己那边活一遍。</p><p>她那边买东西，她要发给我看。</p><p>一张价格牌，她拍下来。</p><p>她说：你看，一盒草莓，三十八。</p><p>我说：抢钱。</p><p>她说：我这里草莓多大。</p><p>她发一张图。</p><p>我说：跟我家那边的一样大。</p><p>她说：不一样，你这个是不懂草莓的人说的话。</p><p>我说：那你说多大。</p><p>她说：像你那个瓶盖。</p><p>我说：你别什么都往瓶盖上说。</p><p>她说：我就说瓶盖怎么了。</p><p>一盒草莓可以说十一句。</p><p>十一句里没有一个字是必要的。</p><p>这就是四百一十条的来源。</p><p>十一月里最好的三天，我到现在都记得。</p><p>第一天是十一号。</p><p>那天我半夜起来上厕所。</p><p>我们那层楼的厕所要走二十米，中间要过一次走廊，走廊的灯是感应的，人走过去它亮。</p><p>我一边往厕所走，一边打字。</p><p>我发：我起来上厕所。</p><p>她回：几点了。</p><p>我发：三点四十。</p><p>她回：我这里七点四十，我刚起。</p><p>我们两个，一个站在走廊感应灯底下，一个坐在自己那边的床边穿袜子。</p><p>她把袜子那只脚抬起来拍照发给我。</p><p>她说，你看我的袜子，一只蓝一只黑。</p><p>我说，为什么。</p><p>她说，因为我在黑暗里摸的。</p><p>我说，你为什么在黑暗里摸。</p><p>她说，因为我这边的太阳六点四十还没出来，我七点四十穿袜子的时候屋里是黑的。</p><p>我站在那条走廊上，穿着一只鞋，看她那只袜子。</p><p>我说，那你现在看得见吗。</p><p>她说，现在能看见一点。</p><p>我说，你把灯开一下。</p><p>她说，不开，我习惯了。</p><p>第二天最好的一天是十九号。</p><p>那天我们吵了一架，吵的是&quot;你今天有没有好好吃饭&quot;。</p><p>吵了两个小时。</p><p>吵完她说了一句：我们居然为了吃饭吵了两小时。</p><p>我说，那不然呢。</p><p>她说，你知道吗，我今天在等一个回我话的人，等到现在。</p><p>她说，我以前十点就睡。</p><p>我说，你现在几点。</p><p>她说，凌晨两点。</p><p>她说，我在等一个不回我话的人，可是你今天回得很快。</p><p>我说，那我以后都回很快。</p><p>她说，你别说这种话。</p><p>我说，为什么。</p><p>她说，因为你说了我就信了。</p><p>我那时候不懂这句话。</p><p>我以为她说的是我要做到。</p><p>她说的其实是：她知道自己信了以后会怎么样。</p><p>第三天是二十七号。</p><p>那天她给我念了一份菜单。</p><p>她在那边一家中餐馆，一个人吃饭，她把菜单从头念到尾。</p><p>她念到&quot;酸辣土豆丝 十二镑&quot;的时候，我说你能不能别念价格。</p><p>她说，为什么。</p><p>我说，你念价格我难受。</p><p>她说，为什么难受。</p><p>我说，因为我不能给你带一份。</p><p>她不说话了。</p><p>过了大概两分钟，她发了一句。</p><p>她说，那我以后只念菜名。</p><p>我说，你今天先念完。</p><p>她说，为什么。</p><p>我说，你念完我就能知道你今天吃了什么，你花了多少钱，你那边的物价是什么样。</p><p>我说，这些东西我都要知道。</p><p>她说，你要这些干什么。</p><p>我说，将来有用。</p><p>她那晚把菜单剩下的十一行全念完了。</p><p>十一月底，我做了一件事。</p><p>我把那个文件拆开，统计了一下谁说了多少。</p><p>我做出来的结果是：</p><p>一万两千三百一十七条里，她发了两千二百条。</p><p>我发了一万零一百多条。</p><p>字数的差更大。</p><p>她那两千二百条，平均一条七个字。</p><p>她那个月的字数，占全部的百分之十八。</p><p>我把这个数在屏幕上看了很久。</p><p>我又拆了一层。</p><p>她那两千二百条里，“嗯”“哦”“好”“行”“在吗”“晚安”这六个词，占了一半。</p><p>也就是说，那一个月她真正跟我说的话，一共一千一百条。</p><p>平均一天三十七条。</p><p>我坐在那儿算：三十七条，够不够说一个人今天怎么样。</p><p>不够。</p><p>我一直以为那个月我们是在说话。</p><p>我以为说话是两个人一人一半。</p><p>后来我才知道，那个月我说的每一句她都接了，可是她接的方式是&quot;嗯&quot;&quot;哦&quot;&quot;好&quot;&quot;在吗&quot;&quot;晚安&quot;。</p><p>她那个月跟我说的话，加起来没有我一天写得多。</p><p>我坐在自习室里，看着那个百分之十八。</p><p>我心里第一个念头很难听，我不愿意写出来。</p><p>第二个念头是这样的：</p><p>原来那个月一直是我在讲话。</p><p>她只是没有走。</p><p>那天晚上我给她发了一句。</p><p>我说，你今天话好少。</p><p>她说，嗯。</p><p>我说，你看，你又嗯。</p><p>她隔了一会儿，回了一句。</p><p>她说，因为我今天在想一件事。</p><p>我说，想什么。</p><p>她说，我在想，你那么多话，我少说话你会不会不高兴。</p><p>我坐在那儿，看着她这一行。</p><p>我说，不会。</p><p>她说，你回答得太快了。</p><p>我说，我是真的不会。</p><p>她说，我知道你不会。</p><p>她说，我就是想跟你说，我以后还是这样。</p><p>我说，哪样。</p><p>她说，少说。</p>',143)])])}const l=t(_,[["render",r]]);export{d as __pageData,l as default};
